import flet as ft

class MyButton(ft.Button):
    def __init__(self, t):
        # super().__init__() に直接プロパティを渡す
        super().__init__(
            content=t,
            bgcolor=ft.Colors.LIGHT_GREEN_100,
            color=ft.Colors.GREEN_800
        )

def main(page: ft.Page):
    bt = MyButton(t="ボタン1")
    page.add(bt)

ft.run(main)
